#include <stdio.h>
#include <stdint.h>
#include <math.h>

int main(void) {
    long long beg = 9007199254740992LL;       // 2^53
    double a = (double)beg;
    double b = 9007199254740992.0;            // float end
    printf("a = %.17g\n", a);
    printf("b = %.17g\n", b);
    if (a > b) { printf("a>b -> empty\n"); return 0; }
    long long cap = (long long)(b - a) + 1;
    printf("cap = %lld\n", cap);
    long long i = 0;
    // inclusive loop, mimic
    double aa = a;
    int guard = 0;
    while (aa <= b) {
        printf("iter i=%lld aa=%.17g  (writing ptr[%lld])\n", i, aa, i);
        i++;
        aa += 1.0;
        if (++guard > 5) { printf("...stall detected, would write OOB at ptr[%lld] (cap=%lld)\n", i, cap); break; }
    }
    printf("final i=%lld cap=%lld -> OOB=%s\n", i, cap, i>cap?"YES":"no");
    return 0;
}
EOF
gcc -O0 -o /tmp/test_range /tmp/test_range.c -lm && /tmp/test_range

